send_js:
const ed = document.querySelector('textarea') || document.querySelector('[contenteditable="true"]');
if (!ed) return 'ERR:no input';
ed.focus();
if (ed.tagName === 'TEXTAREA' || ed.tagName === 'INPUT') {
  const proto = ed.tagName === 'TEXTAREA' ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
  Object.getOwnPropertyDescriptor(proto, 'value').set.call(ed, PROMPT);
  ed.dispatchEvent(new Event('input', {bubbles: true}));
} else {
  document.execCommand('insertText', false, PROMPT);
}
await new Promise(r => setTimeout(r, 300));
ed.dispatchEvent(new KeyboardEvent('keydown', {key:'Enter', code:'Enter', keyCode:13, which:13, bubbles:true, cancelable:true}));
return 'sent';

extract_js:
const els = document.querySelectorAll('.markdown, .message-content, [class*="response"], [class*="answer"], [class*="assistant"], article');
if (!els.length) return '';
return (els[els.length - 1].innerText || '').trim();
